#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Edge {
    int u, v, w;
    bool operator<(const Edge& other) const {
        return w > other.w;
    }
};

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        for (int i = 1; i <= n; ++i) parent[i] = i;
    }
    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }
    bool unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            parent[root_i] = root_j;
            return true;
        }
        return false;
    }
};

const int MAXN = 100005;
const int LOGN = 18;
const int INF = 1e9;

vector<pair<int, int>> adj[MAXN];
int up[MAXN][LOGN];
int min_edge[MAXN][LOGN];
int depth[MAXN];

void dfs(int u, int p, int w, int d) {
    depth[u] = d;
    up[u][0] = p;
    min_edge[u][0] = w;

    for (int i = 1; i < LOGN; ++i) {
        up[u][i] = up[up[u][i - 1]][i - 1];
        min_edge[u][i] = min(min_edge[u][i - 1], min_edge[up[u][i - 1]][i - 1]);
    }

    for (auto& edge : adj[u]) {
        int v = edge.first;
        int weight = edge.second;
        if (v != p) {
            dfs(v, u, weight, d + 1);
        }
    }
}

int query(int u, int v) {
    int ans = INF;
    if (depth[u] < depth[v]) swap(u, v);

    for (int i = LOGN - 1; i >= 0; --i) {
        if (depth[u] - (1 << i) >= depth[v]) {
            ans = min(ans, min_edge[u][i]);
            u = up[u][i];
        }
    }

    if (u == v) return ans;

    for (int i = LOGN - 1; i >= 0; --i) {
        if (up[u][i] != up[v][i]) {
            ans = min({ans, min_edge[u][i], min_edge[v][i]});
            u = up[u][i];
            v = up[v][i];
        }
    }

    ans = min({ans, min_edge[u][0], min_edge[v][0]});
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, b;
    if (!(cin >> n >> b)) return 0;

    vector<Edge> edges(b);
    for (int i = 0; i < b; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }

    sort(edges.begin(), edges.end());

    DSU dsu(n);
    int edges_count = 0;
    for (const auto& edge : edges) {
        if (dsu.unite(edge.u, edge.v)) {
            adj[edge.u].push_back({edge.v, edge.w});
            adj[edge.v].push_back({edge.u, edge.w});
            edges_count++;
            if (edges_count == n - 1) break;
        }
    }

    dfs(1, 1, INF, 0);

    int c;
    if (cin >> c) {
        while (c--) {
            int x, y;
            cin >> x >> y;
            cout << query(x, y) << "\n";
        }
    }

    return 0;
}
